int main(int argc, char *argv[])
{
    struct termios attr;

    tcgetattr(STDIN_FILENO, &attr);
    attr.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &attr);

    int maze = 1;

    if (argc > 1)
    {
        int passkey = strtoul(argv[1], NULL, 10);
        for (int i = 1; i < mazes; i++)
            if (passkey == passkeys[i])
                maze = i + 1;
    }

    int quit = 0;
    int mx, my, cursor, n, b1, b2, flag, steps, dx, cursorPrev, b1o, b2o;
    uint8_t screen[601], screenUndo[601];

    int idx = (maze-1) * 3;
    mx = data1[idx] & 255;
    my = (data1[idx] >> 8) & 255;
    cursorPrev = cursor = (data1[idx+1] & 255) + ((data1[idx+1] >> 8) & 255) * mx + 1;
    n = data1[idx+2];

    b1o = b1 = 0;
    b2o = b2 = 0;
    flag = 0;
    steps = 0;
    dx = 0;

    for (int i = 1; i <= mx * my; i++)
    {
        int b = (data0[n] >> (flag * 2)) & 3;
        flag++;
        if (flag == 4)
        {
            flag = 0;
            n++;
        }
        if (b == 3)
            b = 7;

        screen[i] = b;

        if (b == 2)
            b1++;
    }

    for (int k = 0; k <= 10; k++)
        if (data2[k * 2 + 1] == maze)
            for (int j = data2[k * 2]; j <= data2[k * 2 + 2] - 1; j++)
            {
                int b = (data3[j] & 255) + mx * ((data3[j] >> 8) & 255);
                screen[b] = 3;
                b2++;
                b1++;
            }

    goto draw;

    do
    {
        // printf("\x1b[2J\x1b[H"); // Clear screen
        printf("\x1b[%dA", my + 1); // Move cursor up N lines

        uint8_t kbdInput;

        if (read(STDIN_FILENO, &kbdInput, 1) > 0)
        {
            // printf("Key %d", kbdInput);
            switch (kbdInput)
            {
                case '2':
                case 66:
                    dx = mx;
                    break;
                case '8':
                case 65:
                    dx = -mx;
                    break;
                case '4':
                case 68:
                    dx = -1;
                    break;
                case '6':
                case 67:
                    dx = 1;
                    break;

                case 'u': // Undo
                    if ((steps) && (dx != 0))
                    {
                        memcpy(screen, screenUndo, sizeof(screen));
                        cursor = cursorPrev;
                        b1 = b1o;
                        b2 = b2o;
                        steps--;
                        dx = 0;
                    }
                    break;

                case 'q':
                    quit = 1;
                default:
                    dx = 0;
                    break;
            }
        }

        if (dx != 0)
        {
            if (screen[cursor + dx] < 2)
                cursor += dx;
            else if (((screen[cursor + dx] == 2) ||
                      (screen[cursor + dx] == 3)) &&
                      (screen[cursor + dx + dx] < 2))
            {
                memcpy(screenUndo, screen, sizeof(screen));
                cursorPrev = cursor;
                b1o = b1;
                b2o = b2;

                b2 = b2 - (screen[cursor + dx] & 1) + (screen[cursor + dx + dx] & 1);
                screen[cursor + dx + dx] += 2;
                screen[cursor + dx] -= 2;
                cursor = cursor + dx;
                steps++;
            }
        }

draw:
        printf("\n");

        for (int y = 1; y <= my; y++)
        {
            for (int x = 1; x <= mx; x++)
            {
                int cur = x + (y-1) * mx;
                int b = screen[x + (y-1) * mx];
                if (cur == cursor)
                    b = 6;

                printf("%c%c", figure[b * 2], figure[b * 2 + 1]);
            }

            switch (y)
            {
                case 1:
                    printf("  * Pusher *\n");
                    break;
                case 2:
                    printf(" Maze:  %d\n", maze);
                    break;
                case 3:
                    printf(" Cargo: %d   \n", b1 - b2);
                    break;
                case 4:
                    printf(" Done:  %d   \n", b2);
                    break;
                case 5:
                    printf(" Steps: %d   \n", steps);
                    break;
                default:
                    printf("\n");
                    break;
            }
        }
    } while ((! quit) && (b1 - b2));

    if (! (b1 - b2))
    {
        if (maze < mazes)
            printf("\nSolved!\nNext maze key is: %d\n", passkeys[maze]);
        else
            printf("\nAll mazes are solved. Thanks.\n");
    }

    attr.c_lflag |= (ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &attr);

    return 0;
}
